files.examples/01_rewrites.sql:
CREATE TABLE accounts (
  id   integer PRIMARY KEY,
  name varchar(100) NOT NULL
);
CREATE INDEX accounts_name ON accounts (name);
INSERT INTO accounts SELECT g, 'Kullanıcı ' || g FROM generate_series(1, 1000) AS g;

-- Table and index data live in files named by relfilenode. A rewrite copies
-- everything into new files, so the numbers change. Log them after each step.
CREATE FUNCTION files(OUT tbl oid, OUT idx oid) LANGUAGE sql
  AS $$ SELECT pg_relation_filenode('accounts'), pg_relation_filenode('accounts_name') $$;
CREATE TABLE steps (n int GENERATED ALWAYS AS IDENTITY, change text, tbl oid, idx oid);
INSERT INTO steps (change, tbl, idx) SELECT '(start)', tbl, idx FROM files();

ALTER TABLE accounts ADD COLUMN note text;
INSERT INTO steps (change, tbl, idx) SELECT 'add column, no default', tbl, idx FROM files();
ALTER TABLE accounts ADD COLUMN plan text NOT NULL DEFAULT 'free';
INSERT INTO steps (change, tbl, idx) SELECT 'add column, constant default', tbl, idx FROM files();
ALTER TABLE accounts ADD COLUMN token uuid NOT NULL DEFAULT uuidv7();
INSERT INTO steps (change, tbl, idx) SELECT 'add column, volatile default', tbl, idx FROM files();
ALTER TABLE accounts ADD COLUMN plan_label text GENERATED ALWAYS AS (upper(plan));
INSERT INTO steps (change, tbl, idx) SELECT 'add virtual generated column', tbl, idx FROM files();
ALTER TABLE accounts ALTER COLUMN name TYPE varchar(200);
INSERT INTO steps (change, tbl, idx) SELECT 'varchar(100) -> varchar(200)', tbl, idx FROM files();
ALTER TABLE accounts ALTER COLUMN name TYPE text;
INSERT INTO steps (change, tbl, idx) SELECT 'varchar(200) -> text', tbl, idx FROM files();
ALTER TABLE accounts ALTER COLUMN name TYPE text COLLATE "tr-x-icu";
INSERT INTO steps (change, tbl, idx) SELECT 'collation -> tr-x-icu', tbl, idx FROM files();
ALTER TABLE accounts ALTER COLUMN id TYPE bigint;
INSERT INTO steps (change, tbl, idx) SELECT 'integer -> bigint', tbl, idx FROM files();
ALTER TABLE accounts DROP COLUMN note;
INSERT INTO steps (change, tbl, idx) SELECT 'drop column', tbl, idx FROM files();

SELECT change,
       tbl <> lag(tbl) OVER (ORDER BY n) AS table_rewritten,
       idx <> lag(idx) OVER (ORDER BY n) AS name_index_rebuilt
FROM steps
ORDER BY n;

files.examples/02_lock_levels.sql:
-- Runtime sql-nontx: every statement commits on its own, as in psql, so the
-- table exists before we look at the locks a single ALTER takes.
CREATE TABLE accounts (id bigint PRIMARY KEY, email text NOT NULL);
INSERT INTO accounts SELECT g, 'user' || g || '@example.com' FROM generate_series(1, 1000) AS g;
CREATE VIEW my_locks AS
  SELECT mode FROM pg_locks
  WHERE pid = pg_backend_pid() AND locktype = 'relation' AND relation = 'accounts'::regclass;

BEGIN;
ALTER TABLE accounts ADD COLUMN country text;
SELECT mode FROM my_locks ORDER BY mode;
COMMIT;

BEGIN;
ALTER TABLE accounts ADD CONSTRAINT email_has_at CHECK (email LIKE '%@%') NOT VALID;
SELECT mode FROM my_locks ORDER BY mode;
COMMIT;

BEGIN;
ALTER TABLE accounts VALIDATE CONSTRAINT email_has_at;
SELECT mode FROM my_locks ORDER BY mode;
COMMIT;

BEGIN;
CREATE INDEX accounts_email ON accounts (email);
SELECT mode FROM my_locks ORDER BY mode;
ROLLBACK;

-- The online alternative builds the index without blocking writes, and for
-- exactly that reason it refuses to run inside a transaction block.
BEGIN;
CREATE INDEX CONCURRENTLY accounts_email ON accounts (email);

files.examples/03_safe_order.sql:
CREATE TABLE customers (
  id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  phone text NOT NULL
);
INSERT INTO customers (phone)
SELECT CASE WHEN g % 4 = 0 THEN '+49 30 ' ELSE '+90 212 ' END || (5550000 + g)
FROM generate_series(1, 1000) AS g;

-- Goal: a required country column, derived from each phone number.
-- Step 1: add it nullable and without a default: a catalog-only change.
ALTER TABLE customers ADD COLUMN country text;

-- Step 2: the rule, NOT VALID. No scan, so the exclusive lock is brief, and
-- from now on every inserted or updated row must have a country...
ALTER TABLE customers
  ADD CONSTRAINT customers_country_not_null NOT NULL country NOT VALID;

-- ...while the existing rows are still NULL, and the catalog admits it.
SELECT count(*) AS rows_without_country,
       (SELECT convalidated FROM pg_constraint
        WHERE conrelid = 'customers'::regclass
          AND conname = 'customers_country_not_null') AS validated
FROM customers
WHERE country IS NULL;

-- Step 3: backfill in batches; in production, one short transaction each.
UPDATE customers SET country = CASE WHEN phone LIKE '+90%' THEN 'TR' ELSE 'DE' END
WHERE id BETWEEN 1 AND 500;
UPDATE customers SET country = CASE WHEN phone LIKE '+90%' THEN 'TR' ELSE 'DE' END
WHERE id BETWEEN 501 AND 1000;

-- Step 4: VALIDATE scans under SHARE UPDATE EXCLUSIVE: reads and writes go on.
ALTER TABLE customers VALIDATE CONSTRAINT customers_country_not_null;

SELECT count(*) AS rows_without_country,
       (SELECT convalidated FROM pg_constraint
        WHERE conrelid = 'customers'::regclass
          AND conname = 'customers_country_not_null') AS validated
FROM customers
WHERE country IS NULL;

-- The constraint has guarded every write since step 2.
INSERT INTO customers (phone) VALUES ('+90 312 5550000');
